import {deflateSync,inflateSync} from 'node:zlib';
export function crc(bytes){let value=0xffffffff;for(const byte of bytes){value^=byte;for(let i=0;i<8;i++)value=(value>>>1)^((value&1)?0xedb88320:0);}return (value^0xffffffff)>>>0;}
export function chunk(type,data){const bytes=Buffer.alloc(data.length+12);bytes.writeUInt32BE(data.length);bytes.write(type,4);bytes.set(data,8);bytes.writeUInt32BE(crc(bytes.subarray(4,-4)),bytes.length-4);return bytes;}
export function importPNG({level=0,width=1024,height=512}={}){const header=Buffer.alloc(13);header.writeUInt32BE(width);header.writeUInt32BE(height,4);header[8]=8;header[9]=6;const raw=Buffer.alloc((width*4+1)*height);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=y*(width*4+1)+1+x*4;raw[i]=x%256;raw[i+1]=y%256;raw[i+2]=117;raw[i+3]=x%3?255:40;}const png=Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',header),chunk('gAMA',Buffer.from([0,0,177,143])),chunk('tEXt',Buffer.from('CRIS\0Import QA')),chunk('IDAT',deflateSync(raw,{level})),chunk('IEND',Buffer.alloc(0))]);return {blob:new Blob([png],{type:'image/png'}),raw};}
export async function pngParts(blob){const bytes=Buffer.from(await blob.arrayBuffer()),chunks=[],idat=[];for(let at=8;at<bytes.length;){const length=bytes.readUInt32BE(at),type=bytes.toString('ascii',at+4,at+8),payload=bytes.subarray(at+8,at+8+length);if(bytes.readUInt32BE(at+8+length)!==crc(bytes.subarray(at+4,at+8+length)))throw Error('CRC mismatch');chunks.push({type,payload});if(type==='IDAT')idat.push(payload);at+=length+12;}return {chunks,raw:inflateSync(Buffer.concat(idat))};}
